# Founder's story: "My Journey" (imported by build.py). English text as written by Dr Sumit Konar; Bengali translation.

EN = ["I was born in Galigram, a small village in the Bardhaman district of West Bengal, now known as Purba Bardhaman. I grew up in an ordinary family and studied at Galsi High School, a Bengali-medium village school, until Class 12. At that time, I had very little idea where my education would eventually take me.",
"After school, I moved to Kolkata to study at Ramakrishna Mission Residential College, Narendrapur. It was an important turning point in my life. My education, accommodation and food cost just ₹1,100 per month. That opportunity made higher education possible for someone from a modest background like mine.",
"From Narendrapur, I went to IIT Madras in Chennai for my MSc in Chemistry. Later, I took the GRE and TOEFL examinations and travelled to the United States to begin my PhD at Arizona State University. When my research supervisor moved to Stockholm University in Sweden, I followed him and completed my PhD there.",
"My journey continued to Scotland, where I joined the University of Edinburgh as a postdoctoral researcher. In 2022, I took up a permanent position at the University of Lincoln in England. Today, I have made the United Kingdom my home.",
"Looking back, it has been a remarkable journey from a small Bengali-medium village school to universities in India, the United States, Sweden and the United Kingdom. But I do not believe that my story is particularly extraordinary. There are countless children growing up in villages and small towns who are just as capable, curious and ambitious. What they often lack is access to information, guidance and people who can show them what is possible.",
"That is one of the main reasons I started BiswaPath (বিশ্বপাঠ).",
"I want students, particularly those from ordinary families and Bengali-medium backgrounds, to know that studying at a good university, conducting research or pursuing an education abroad is not beyond their reach. There are opportunities, scholarships and different pathways, but finding reliable information can be difficult when you do not know where to begin.",
"I also believe that education is not simply about leaving one's home and settling in another country. Some students may choose to return to India or Bangladesh and contribute to their local communities. Others may build their lives abroad, as I have. Both choices are equally valuable. What matters is how we use our education, knowledge and experience to make a difference.",
"Through BiswaPath, I hope to bring together students, teachers, researchers, academics and professionals from around the world. Many of us have travelled different paths, faced similar uncertainties and learned valuable lessons along the way. By sharing those experiences, we can make the journey a little easier for the next generation.",
"I cannot do this alone, and I do not want BiswaPath to be just my personal project. My hope is that it will gradually become a collective, collaborative educational initiative where people help one another, share reliable information and create opportunities for students who may otherwise never hear about them.",
"My journey began in a small village in Bengal. BiswaPath is my attempt to help others discover how far their own journeys can take them."]

BN = ["আমার জন্ম পশ্চিমবঙ্গের বর্ধমান জেলার (এখন পূর্ব বর্ধমান) ছোট্ট একটা গ্রাম, গলিগ্রামে। খুব সাধারণ পরিবারে বড় হয়েছি, আর ক্লাস টুয়েলভ পর্যন্ত পড়েছি গ্রামের বাংলা-মাধ্যম স্কুল গলসি হাই স্কুলে। তখন আমার কোনো ধারণাই ছিল না, পড়াশোনা আমাকে শেষ পর্যন্ত কোথায় নিয়ে যাবে।",
"স্কুলের পর পড়তে গেলাম কলকাতার কাছে রামকৃষ্ণ মিশন রেসিডেনশিয়াল কলেজ, নরেন্দ্রপুরে। সেটা ছিল আমার জীবনের একটা বড় মোড়। পড়াশোনা, থাকা আর খাওয়া মিলিয়ে মাসে খরচ ছিল মাত্র ₹১,১০০। আমার মতো সাধারণ পরিবারের ছেলের কাছে উচ্চশিক্ষা সম্ভব হয়েছিল ওই সুযোগের জন্যই।",
"নরেন্দ্রপুর থেকে চেন্নাইয়ের IIT Madras-এ গেলাম কেমিস্ট্রিতে MSc করতে। পরে GRE আর TOEFL পরীক্ষা দিয়ে আমেরিকার Arizona State University-তে PhD শুরু করলাম। আমার রিসার্চ সুপারভাইজার যখন সুইডেনের Stockholm University-তে চলে গেলেন, আমিও তাঁর সঙ্গে গেলাম, আর সেখানেই PhD শেষ করলাম।",
"তারপর স্কটল্যান্ডে, University of Edinburgh-এ postdoctoral researcher হিসেবে যোগ দিলাম। ২০২২ সালে ইংল্যান্ডের University of Lincoln-এ স্থায়ী পদে কাজ শুরু করি। আজ UK-ই আমার ঘর।",
"পেছনে তাকালে মনে হয়, গ্রামের একটা ছোট বাংলা-মাধ্যম স্কুল থেকে ভারত, আমেরিকা, সুইডেন আর UK-র বিশ্ববিদ্যালয় পর্যন্ত — যাত্রাটা সত্যিই অসাধারণ। কিন্তু আমি মনে করি না আমার গল্পটা আলাদা কিছু। গ্রামে আর ছোট শহরে অসংখ্য ছেলেমেয়ে বড় হচ্ছে, যারা ঠিক ততটাই মেধাবী, কৌতূহলী আর উচ্চাকাঙ্ক্ষী। তাদের যা প্রায়ই থাকে না, তা হল তথ্য, সঠিক দিশা, আর এমন মানুষ যাঁরা দেখিয়ে দিতে পারেন কী কী সম্ভব।",
"বিশ্বপাঠ (BiswaPath) শুরু করার এটাই একটা বড় কারণ।",
"আমি চাই ছাত্রছাত্রীরা — বিশেষ করে সাধারণ পরিবারের আর বাংলা-মাধ্যম থেকে আসা ছেলেমেয়েরা — জানুক যে ভালো বিশ্ববিদ্যালয়ে পড়া, গবেষণা করা বা বিদেশে পড়তে যাওয়া তাদের নাগালের বাইরে নয়। সুযোগ আছে, স্কলারশিপ আছে, আলাদা আলাদা পথ আছে। কিন্তু কোথা থেকে শুরু করতে হবে না জানলে নির্ভরযোগ্য তথ্য খুঁজে পাওয়া কঠিন।",
"আমি এটাও বিশ্বাস করি যে শিক্ষা মানে শুধু বাড়ি ছেড়ে অন্য দেশে থিতু হওয়া নয়। কেউ হয়তো ভারত বা বাংলাদেশে ফিরে গিয়ে নিজের এলাকার জন্য কাজ করবে। কেউ আবার আমার মতো বিদেশে জীবন গড়বে। দুটো পথই সমান মূল্যবান। আসল কথা হল, আমাদের শিক্ষা, জ্ঞান আর অভিজ্ঞতা দিয়ে আমরা কী পরিবর্তন আনতে পারি।",
"বিশ্বপাঠের মাধ্যমে আমি সারা পৃথিবীর ছাত্রছাত্রী, শিক্ষক, গবেষক, অধ্যাপক আর পেশাদারদের এক জায়গায় আনতে চাই। আমরা অনেকেই আলাদা আলাদা পথে হেঁটেছি, একই রকম অনিশ্চয়তার মুখোমুখি হয়েছি, আর পথে অনেক কিছু শিখেছি। সেই অভিজ্ঞতা ভাগ করে নিলে পরের প্রজন্মের যাত্রাটা একটু সহজ হতে পারে।",
"আমি একা এটা করতে পারব না, আর আমি চাই না বিশ্বপাঠ শুধু আমার ব্যক্তিগত প্রকল্প হয়ে থাকুক। আমার আশা, ধীরে ধীরে এটা একটা সম্মিলিত, সবাই মিলে গড়া শিক্ষার উদ্যোগ হয়ে উঠবে — যেখানে মানুষ একে অপরকে সাহায্য করবে, নির্ভরযোগ্য তথ্য ভাগ করবে, আর এমন ছাত্রছাত্রীদের জন্য সুযোগ তৈরি করবে, যারা হয়তো অন্যথায় সেগুলোর কথা কোনোদিন শুনতেই পেত না।",
"আমার যাত্রা শুরু হয়েছিল বাংলার একটা ছোট গ্রাম থেকে। বিশ্বপাঠ আমার একটা চেষ্টা — যাতে অন্যরাও খুঁজে পায়, তাদের নিজের যাত্রা তাদের কতদূর নিয়ে যেতে পারে।"]

STOPS = [("Galigram, Purba Bardhaman", "গলিগ্রাম, পূর্ব বর্ধমান", "Galsi High School, Bengali medium, to Class 12", "গলসি হাই স্কুল, বাংলা মাধ্যম, ক্লাস টুয়েলভ পর্যন্ত"),
         ("Narendrapur, Kolkata", "নরেন্দ্রপুর, কলকাতা", "Ramakrishna Mission Residential College", "রামকৃষ্ণ মিশন রেসিডেনশিয়াল কলেজ"),
         ("Chennai", "চেন্নাই", "MSc Chemistry, IIT Madras", "MSc কেমিস্ট্রি, IIT Madras"),
         ("Arizona, USA", "অ্যারিজোনা, USA", "PhD begins, Arizona State University", "PhD শুরু, Arizona State University"),
         ("Stockholm, Sweden", "স্টকহোম, সুইডেন", "PhD completed, Stockholm University", "PhD শেষ, Stockholm University"),
         ("Edinburgh, Scotland", "এডিনবরা, স্কটল্যান্ড", "Postdoctoral researcher, University of Edinburgh", "Postdoctoral researcher, University of Edinburgh"),
         ("Lincoln, England", "লিংকন, ইংল্যান্ড", "Permanent post, University of Lincoln (2022)", "স্থায়ী পদ, University of Lincoln (২০২২)")]

def content(lang):
    E = lang == "en"
    title = "My journey: from a small village in Bengal to the world" if E else "আমার যাত্রা: বাংলার ছোট্ট গ্রাম থেকে বিশ্বে"
    desc = ("Dr Sumit Konar, founder of BiswaPath, on going from a Bengali-medium village school to universities in India, the USA, Sweden and the UK — and why he started BiswaPath."
            if E else "বিশ্বপাঠের প্রতিষ্ঠাতা ড. সুমিত কোনার: গ্রামের বাংলা-মাধ্যম স্কুল থেকে ভারত, আমেরিকা, সুইডেন আর UK-র বিশ্ববিদ্যালয়ে — আর কেন বিশ্বপাঠ শুরু করলেন।")
    stops = "".join(f'<li class="stop"><h3>{s[0] if E else s[1]}</h3><p>{s[2] if E else s[3]}</p></li>' for s in STOPS)
    paras = "".join(f"<p>{p}</p>" for p in (EN if E else BN))
    sig = ("<p><b>Dr Sumit Konar</b><br>Founder, BiswaPath (বিশ্বপাঠ)</p>" if E else "<p><b>ড. সুমিত কোনার</b><br>প্রতিষ্ঠাতা, বিশ্বপাঠ (BiswaPath)</p>")
    other = ('<p class="updated">এই লেখাটি <a href="/bn/my-journey/">বাংলায় পড়ুন</a>।</p>' if E
             else '<p class="updated">মূল লেখাটি ইংরেজিতে; <a href="/my-journey/">ইংরেজিতে পড়ুন</a>।</p>')
    inner = f"""{other}
<ol class="stops journey" aria-label="{'The journey, step by step' if E else 'যাত্রা, ধাপে ধাপে'}">{stops}</ol>
{paras}
{sig}
<div class="invite"><p>{'Have you travelled a similar path? Share your story or help a student who is just starting.' if E else 'আপনিও কি এমন পথে হেঁটেছেন? আপনার গল্প ভাগ করুন, বা সবে শুরু করা কোনো ছাত্রকে সাহায্য করুন।'} <a href="{'/contribute/' if E else '/bn/contribute/'}">{'Join BiswaPath' if E else 'বিশ্বপাঠে যুক্ত হোন'}</a></p></div>"""
    return title, desc, inner
